TLM.f("Tempora/Quadp3-5",{"officium":"Feria VI post Cineres","rule":["no Gloria","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;","Super populum"],"ruleInherited":["no Gloria","Credo","Prefatio=Trinitate","Suffr=Maria2;Sanctorum,Ecclesiæ;;"],"fallback":"Tempora/Quadp3-0","from":{"GradualeF":"Tempora/Quadp3-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 29:11"},{"k":"text","la":"Audívit Dóminus, et misértus est mihi: Dóminus factus est adjútor meus."},{"k":"ref","la":"Ps 29:2"},{"k":"text","la":"Exaltábo te, Dómine, quóniam suscepísti me: nec delectásti inimícos meos super me."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Audívit Dóminus, et misértus est mihi: Dóminus factus est adjútor meus."}],"Oratio":[{"k":"text","la":"Inchoáta jejúnia, quǽsumus, Dómine, benígno favore proséquere: ut observántiam, quam corporáliter exhibémus, méntibus étiam sincéris exercére valeámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Isaíæ Prophétæ."},{"k":"ref","la":"Isa 58:1-9"},{"k":"text","la":"Hæc dicit Dóminus Deus: Clama, ne cesses: quasi tuba exálta vocem tuam: et annúntia pópulo meo scélera eórum, et dómui Jacob peccáta eórum. Me étenim de die in diem quærunt, et scire vias meas volunt: quasi gens, quæ justítiam fécerit, et judícium Dei sui non derelíquerit: rogant me judícia justítiæ: appropinquáre Deo volunt. Quare jejunávimus, et non aspexísti: humiliávimus ánimas nostras, et nescísti? Ecce, in die jejúnii vestri invénitur volúntas vestra, et omnes debitóres vestros repétitis. Ecce, ad lites et contentiónes jejunátis, et percútitis pugno ímpie. Nolíte jejunáre sicut usque ad hanc diem, ut audiátur in excélso clamor vester. Numquid tale est jejúnium, quod elégi, per diem afflígere hóminem ánimam suam? numquid contorquére quasi círculum caput suum, et saccum et cínerem stérnere? numquid istud vocábis jejúnium, et diem acceptábilem Dómino? Nonne hoc est magis jejúnium quod elégi? dissólve colligatiónes impietátis, solve fascículos depriméntes: dimítte eos, qui confrácti sunt, líberos, et omne onus dirúmpe. Frange esuriénti panem tuum, et egénos vagósque induc in domum tuam: cum víderis nudum, operi eum, et carnem tuam ne despéxeris. Tunc erúmpet quasi mane lumen tuum, et sánitas tua cítius oriétur, et anteíbit fáciem tuam justítia tua, et glória Dómini cólligete. Tunc invocábis, et Dóminus exáudiet: clamábis, et dicet: Ecce, adsum. Quia miséricors sum, Dóminus, Deus tuus."}],"Graduale":[{"k":"ref","la":"Ps 26:4"},{"k":"text","la":"Unam pétii a Dómino, hanc requíram, ut inhábitem in domo Dómini,"},{"k":"text","la":"Ut vídeam voluptátem Dómini, et prótegar a templo sancto ejus.","mark":"V"},{"k":"ref","la":"Ps 102:10"},{"k":"text","la":"Dómine, non secúndum peccáta nostra, quæ fécimus nos: neque secúndum iniquitátes nostras retríbuas nobis"},{"k":"ref","la":"Ps 78:8-9"},{"k":"text","la":"Dómine, ne memíneris iniquitátum nostrarum antiquarum: cito antícipent nos misericórdiæ tuæ, quia páuperes facti sumus nimis. (Hic genuflectitur)"},{"k":"text","la":"Adjuva nos, Deus, salutáris noster: et propter glóriam nóminis tui, Dómine, libera nos: et propítius esto peccátis nostris, propter nomen tuum.","mark":"V"}],"GradualeF":[{"k":"ref","la":"Ps 76:15; 76:16"},{"k":"text","la":"Tu es Deus qui facis mirabília solus: notam fecísti in géntibus virtútem tuam."},{"k":"text","la":"Liberásti in bráchio tuo pópulum tuum, fílios Israël et Joseph.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum."},{"k":"ref","la":"Matt 5:43-48; 6:1-4"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Audístis, quia dictum est: Diliges próximum tuum, et ódio habébis inimícum tuum. Ego autem dico vobis: Dilígite inimícos vestros, benefácite his, qui odérunt vos, et oráte pro persequéntibus et calumniántibus vos, ut sitis fílii Patris vestri, qui in cœlis est: qui solem suum oriri facit super bonos et malos, et pluit super justos et injústos. Si enim dilígitis eos, qui vos díligunt, quam mercédem habébitis? nonne et publicáni hoc fáciunt? Et si salutavéritis fratres vestros tantum, quid ámplius fácitis? nonne et éthnici hoc fáciunt? Estóte ergo vos perfécti, sicut et Pater vester cœléstis perféctus est. Atténdite, ne justítiam vestram faciátis coram homínibus, ut videámini ab eis: alióquin mercédem non habébitis apud Patrem vestrum, qui in cœlis est. Cum ergo facis eleemósynam, noli tuba cánere ante te, sicut hypócritæ fáciunt in synagógis et in vicis, ut honorificéntur ab homínibus. Amen, dico vobis, recepérunt mercédem suam. Te autem faciénte eleemósynam, nésciat sinístra tua, quid fáciat déxtera tua, ut sit eleemósyna tua in abscóndito, et Pater tuus, qui videt in abscóndito, reddet tibi."}],"Offertorium":[{"k":"ref","la":"Ps 118:154; 118:125"},{"k":"text","la":"Dómine, vivífica me secúndum elóquium tuum: ut sciam testimónia tua."}],"Secreta":[{"k":"text","la":"Sacrifícium, Dómine, observántiæ quadragesimális, quod offérimus, præsta, quǽsumus: ut tibi et mentes nostras reddat accéptas, et continéntiæ promptióris nobis tríbuat facultátem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 2:11-12"},{"k":"text","la":"Servite Dómino in timóre, et exsultáte ei cum tremóre: apprehéndite disciplínam, ne pereátis de via justa."}],"Postcommunio":[{"k":"text","la":"Spíritum nobis, Dómine, tuæ caritátis infúnde: ut, quos uno pane cœlésti satiásti, tua fácias pietáte concórdes."},{"k":"macro","name":"Per Dominum eiusdem"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Tuére, Dómine, pópulum tuum et ab ómnibus peccátis cleménter emúnda: quia nulla ei nocébit advérsitas, si nulla ei dominétur iníquitas."},{"k":"macro","name":"Per Dominum"}]},"hr":{"b35396e89743b495":{"t":"Ps 29, 11, Ps 29, 2\n(Ps 29, 11) Gospodin me je čuo i smilovao se meni. Gospodin je postao moj pomoćnik. (Ps 29, 2) Veličat ću te, Gospodine, jer si me odabrao, nisi dao da se moji neprijatelji raduju nada mnom.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 29, 11) Gospodin me je čuo i smilovao se meni. Gospodin je postao moj pomoćnik.","kn":"(P,s. 29, 11)., Cuo je Gospodin ismilovao se\"^ meni. Gospodin je postao spašiteij moj (Bs. .129' 2) Hvalim Te, Gospodine, jer ši me .uzdigao i nisi 'dopustio da se neprijatelji , moji vesele nada mnom. Slava Ocu . . . Cuo je Gospodin ...","knRef":"Kniewald 1942, str. 104–105 (snimka 53) (OCR)"},"04c4e04694a79047":{"t":"<i>Pomolimo se</i>.\nZapočete postove, molimo, Gospodine prati dobrostivom blagonaklonošću, da odricanje što ga tjelesno obavljamo možemo izvršavati iskrenim duhom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine. ■ prati ^dobrostivom Sklonošću naš započeti post,., da. ono, što tjelesno cimmo, uzmognemo vršiti iskrenim dušama, po G; n. I. K: : , .","knRef":"Kniewald 1942, str. 104–105 (snimka 53) (OCR)"},"455e823898480c01":{"t":"Iz 58, 1-9\nČitanje Izaije proroka. Ovo govori Gospodin Bog: Viči bez prestanka, podigni svoj glas kao trublju i objavi mome narodu njegova bezakonja, a Jakovljevu domu njegove grijehe. Traže me neprestano, žele znati moje namjere. Žele se približiti Bogu kao narod, koji živi po pravdi i ne ostavlja sud svoga Boga, prose od mene pravednu osudu. Zašto smo postili, a ti se na to nisi ni obazreo, i ponizili se, a ti nam toga ne priznaješ? Evo, kada postite, ispunjavate svoju volju i tjerate svoje dužnike. Postite da se prepirete i svađate i teško se tučete pesnicama. Ne postite više tako da se vaš glas čuje do neba. Zar sam ja odabrao takav post da se čovjek muči čitav dan? Ili da savija svoju glavu kao kotač ili da leži u kostrijeti i u pepelu? Je li to pravi post i Gospodinu ugodan dan? Post je što sam ga ja odabrao ovaj: raskini veze bezbožnosti, odriješi uze što pritišću, potlačenima daj slobodu i skini svaki jaram. Lomi gladnome svoj kruh, siromasima i putnicima daj konak pod svojim krovom, zaodjeni gola, ne prezri svoga brata. Tada će tvoje svjetlo sinuti kao zora, brzo će ti se povratiti zdravlje. Tvoja će pravda ići pred tobom i obujmit će te Gospodnja slava. Zazivat ćeš, i Gospodin će uslišati, vapit ćeš, i odgovorit će: Evo me, ja sam milosrdni Gospodin Bog tvoj!"},"0ba4d98a46b74b2a":{"t":"Ps 26, 4\nJedno samo molim od Gospodina, samo ovo tražim: da stanujem u domu Gospodnjem, da gledam ljupkost Gospodnju da se sklonim u sveti hram njegov.\n\nPs 102, 10, Ps 78, 8-9\n(Ps 102, 10) Gospodine, ne uzvrati nam prema našim grijesima koje smo učinili, niti prema našim krivicama. (Ps 78, 8-9) Gospodine, ne sjećaj se naših starih zloća, brzo neka nam dođe ususret tvoje milosrđe, jer postadosmo vrlo bijedni. [Ovdje se poklekne] Pomozi nam, Bože Spasitelju naš, i radi slave svojeg imena izbavi nas, Gospodine. Imaj samilosti s našim grijesima radi imena svojega.","kn":"(Ps. 26, 4). Za jedno samo. molim, Gospodine i samo to tražim, da stanujem u domu Gospodnjemu u sve dane moga života. Da vidim Gospodine i da posjetim njegov hram.\n\n(Ps. 102, 10). Gospodine, ne postupaj s nama po grijesima našim i ne vraćaj nam po nepravdama našim. (Ps. 78, 8, 9) Gospodine, ne opominji se pređašnjih bezakonja naših, već neka nas brzo preteče milosrđe Tvoje, jer smo postali veoma ubogi (Ovdje se poklekne.) Pomozi nam. Bože, spasitelju naš, i radi slave imena svoga izbavi nas. Gospodine, i očisti nas od grijeha naših radi imena svoga.","knRef":"Kniewald 1942, str. 774–775 (snimka 388) (OCR)"},"415e3b7715fefde5":{"t":"Mt 5, 43-48 et 6, 1-4\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme Isus reče svojim učenicima: Čuli ste da je rečeno: Ljubi svoga bližnjega, a ne ljubi svoga neprijatelja. A ja vam kažem: Ljubite svoje neprijatelje, činite dobro onima koji vas mrze i molite se za one koji vas progone i kleveću, da budete prava djeca svoga nebeskog Oca koji daje da njegovo sunce izlazi nad zlima i dobrima i pada kiša pravednima i nepravednima. Ako ljubite one koji vas ljube, kakvu ćete imati plaću? Zar to ne čine tako i carinici? Ako pozdravljate samo svoju braću, što posebno činite? Ne rade li to i nevjernici? Budite, dakle, savršeni kao što je savršen vaš nebeski Otac. Pazite da svojih dobrih djela ne činite pred ljudima, da vas oni vide, jer nećete imati plaće kod svoga nebeskog Oca. Tako i kad dijeliš milostinju, ne trubi pred sobom kao što to čine licemjeri po zbornicama i na ulicama, da ih ljudi časte. Zaista vam kažem, oni su već primili svoju plaću. A kad ti dijeliš milostinju, neka ti ne zna ljevica, što ti radi desnica, tako da tvoja milostinja bude tajna, a uzvratit će ti tvoj Otac koji vidi u tajnosti."},"e377320db8d2b6d1":{"t":"Ps 118, 154 i 125\nOživi me, Gospodine, po riječi tvojoj, utisni mi u srce naredbe svoje.","kn":"(Ps. 118, 154, 125). Gospodine, oživi me, !po riječi svojoj, da spoznam svjedočanstva Tvoja.","knRef":"Kniewald 1942, str. 106–107 (snimka 54) (OCR)"},"50a7cd13cc332310":{"t":"Podaj, molimo, Gospodine, da žrtva korizmenog posta koju prikazujemo učini i naše duše tebi milima i udijeli nam sposobnost spremnijeg odricanja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, Gospodine, da žrtva, što je prmosimo u korizmenom postu, učini naše duše Tebi prijatnimai i da nam dade snagu spremnijeg svladavanja, p. G. n.","knRef":"Kniewald 1942, str. 106–107 (snimka 54) (OCR)"},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo 1 spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože. koji tjelesnim postom obuzdavaš opačine, duh dižeš, daješ krepost i nagrade,' po Kristu, Gospodinu našemu; po kojem veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te 1 nebeske Red i čin sv. mise moći i blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"0f5686ae25f2ecdf":{"t":"Ps 2, 11-12\nSlužite Gospodinu u strahopoštovanju, kličite mu u predanju duše, prihvatite njegovu nauku da ne skrenete s pravog puta."},"0b3a7c2c3a9d7bae":{"t":"<i>Pomolimo se</i>.\nUlij nam, Gospodine, Duh ljubavi svoje, da nas koje si nahranio jednim nebeskim kruhom učiniš jednodušnima po svojoj očinskoj dobroti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ulij nam, Gospoidine, duh ljubavi svoje, da svojom milostivošću učiniš složnima, koje si nahranio vazmenim tajnama, po G. n.","knRef":"Kniewald 1942, str. 298–299 (snimka 150) (OCR)"},"8768b24bfae45b3d":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nBrani, Gospodine, svoj narod i milostivo ga očisti od svih grijeha, jer mu neće naškoditi nikakva protivština ako njim ne vlada nikakva opačina.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pomolimo se! Prignite iponizno glave svoje pred Bogom! Štiti, Gospodine, puk svoj i očisti ga milostivo od svih grijeha, jer mu ne će škoditi nijedna protivština, ako nad njim ' ne vlada nijedna zloća, po G. n.","knRef":"Kniewald 1942, str. 106–107 (snimka 54) (OCR)"}}});
